// Arma el aviso semanal del control contra Magnus: texto simple + versión HTML con tarjetas y botón.
const r = $input.first().json;
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const url = r.portal_url || 'http://127.0.0.1:8000/#/magnus';
const tarjeta = (n, t, color) => `<td style="padding:12px;text-align:center;border:1px solid #e5e7eb;border-radius:8px"><div style="font-size:26px;font-weight:700;color:${color}">${n}</div><div style="font-size:12px;color:#6b7280">${t}</div></td>`;
const primeros = (r.primeros_faltantes || []).map(esc).join(', ');
const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;max-width:640px;margin:0 auto;color:#111827">
  <div style="background:#1e3a5f;color:#fff;padding:18px 22px;border-radius:10px 10px 0 0">
    <div style="font-size:12px;opacity:.8;letter-spacing:.04em">PORTAL DE DOCUMENTACIÓN · SERVELEC</div>
    <div style="font-size:20px;font-weight:600;margin-top:4px">Control contra Magnus</div>
  </div>
  <div style="border:1px solid #e5e7eb;border-top:0;padding:20px 22px;border-radius:0 0 10px 10px">
    <p style="font-size:15px;margin:0 0 14px">Se comparó la exportación de Magnus (<b>${esc(r.archivo)}</b>, ${esc(r.fecha)}) con las planillas y el catálogo del portal.</p>
    <table style="width:100%;border-spacing:8px 0"><tr>
      ${tarjeta(r.faltan, 'faltan en Magnus', r.faltan ? '#b45309' : '#047857')}
      ${tarjeta(r.distinta, 'con descripción distinta', r.distinta ? '#b45309' : '#047857')}
      ${tarjeta(r.solo_magnus, 'solo en Magnus', '#1e3a5f')}
    </tr></table>
    ${primeros ? `<p style="font-size:13px;margin:16px 0 0"><b>Primeros códigos que faltan:</b> ${primeros}</p>` : ''}
    <p style="margin:20px 0 6px"><a href="${esc(url)}" style="background:#1e3a5f;color:#fff;text-decoration:none;padding:10px 18px;border-radius:6px;font-size:14px;display:inline-block">Ver y descargar el informe</a></p>
    <p style="color:#6b7280;font-size:12px;margin:10px 0 0">Este control solo informa: no modifica planillas ni Magnus.</p>
  </div>
</div>`;
const texto = `Control contra Magnus (${r.fecha}): ${r.faltan} código(s) faltan en Magnus, ${r.distinta} con descripción distinta, ${r.solo_magnus} solo en Magnus.` +
  (primeros ? `\nPrimeros que faltan: ${(r.primeros_faltantes || []).join(', ')}` : '') + `\n${url}`;
return [{ json: { asunto: `Portal SERVELEC: control contra Magnus (${r.faltan} faltan, ${r.distinta} distintas)`, texto, html } }];
